create table if not exists provider_configs(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,channel_id uuid references channels(id) on delete cascade,project_id uuid references projects(id) on delete cascade,type text not null,name text not null,model text,secret_ciphertext text,enabled boolean not null default true,config jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists provider_health(id uuid primary key default gen_random_uuid(),provider_config_id uuid references provider_configs(id) on delete cascade,status text not null,latency_ms int,error_rate numeric(6,3) default 0,checked_at timestamptz not null default now());
